const raw = $input.first().json;

let parsed;
if (typeof raw === 'string') {
  try {
    const cleaned = raw.replace(/```json|```/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    return [{ json: { success: false, error: 'JSON parse failed', raw } }];
  }
} else {
  parsed = raw;
}

if (!parsed.task_name || typeof parsed.task_name !== 'string') {
  return [{ json: { success: false, error: 'Missing task_name', raw } }];
}

const VALID_CONFIDENCE = ['high', 'medium', 'low'];
const confidence = VALID_CONFIDENCE.includes(parsed.confidence) ? parsed.confidence : 'medium';

const READ_ONLY_TYPES = ['formula', 'rollup', 'created_time', 'last_edited_time', 'unique_id'];
const schema = $node['Transform Schema'].json.fields;
const schemaMap = Object.fromEntries(schema.map(f => [f.name, f]));

const validFields = {};
const skipped = [];
const invalid = [];

for (const [key, value] of Object.entries(parsed.fields ?? {})) {
  const fieldDef = schemaMap[key];

  if (!fieldDef) {
    invalid.push({ field: key, reason: 'Not in schema' });
    continue;
  }

  if (READ_ONLY_TYPES.includes(fieldDef.type)) {
    skipped.push({ field: key, reason: 'Read-only' });
    continue;
  }

  if (typeof value === 'object' && !Array.isArray(value) && value !== null) {
    invalid.push({ field: key, reason: 'Value is an object, expected string or array' });
    continue;
  }

  if (fieldDef.type === 'select' && fieldDef.options && !fieldDef.options.includes(value)) {
    invalid.push({ field: key, reason: '"' + value + '" not in options: ' + fieldDef.options.join(', ') });
    continue;
  }

  if (fieldDef.type === 'status' && fieldDef.options && !fieldDef.options.includes(value)) {
    invalid.push({ field: key, reason: '"' + value + '" not in status options: ' + fieldDef.options.join(', ') });
    continue;
  }

  if (fieldDef.type === 'multi_select' && fieldDef.options) {
    if (!Array.isArray(value)) {
      invalid.push({ field: key, reason: 'multi_select value must be an array' });
      continue;
    }
    const badOptions = value.filter(v => !fieldDef.options.includes(v));
    if (badOptions.length > 0) {
      invalid.push({ field: key, reason: 'Invalid options: ' + badOptions.join(', ') });
      continue;
    }
  }

  validFields[key] = value;
}

return [{
  json: {
    success: true,
    confidence,
    notes: parsed.notes ?? '',
    task_name: parsed.task_name,
    valid_fields: validFields,
    skipped,
    invalid,
  }
}];

const items = $input.all();

const schemaPrompt = items[0].json.schema;
const email = items[1].json;

const schemaJsonMatch = schemaPrompt.match(/\{[\s\S]*\}/);
const schema = JSON.parse(schemaJsonMatch[0]);
const schemaMap = Object.fromEntries(schema.fields.map(f => [f.name, f]));
const READ_ONLY = ['formula', 'rollup', 'created_time', 'last_edited_time', 'unique_id'];

function stripEmoji(s) { return (s ?? '').replace(/[\u{1F300}-\u{1FAFF}]/gu, '').replace(/^[\s\W]+/, '').trim(); }

function safeSelect(field, value) {
  const opts = field.options ?? [];
  return opts.includes(value) ? value : (opts[0] ?? null);
}

function safeMultiSelect(field, values) {
  const opts = field.options ?? [];
  return values.filter(v => opts.includes(v));
}

function inferPriority(field, subject, snippet) {
  const t = ((subject ?? '') + ' ' + (snippet ?? '')).toLowerCase();
  const raw = /urgent|asap|critical|life/.test(t) ? 'High'
             : /fyi|newsletter|unsubscribe/.test(t) ? 'Low'
             : 'Medium';
  return safeSelect(field, raw);
}

function inferCategory(field, subject, snippet) {
  const t = ((subject ?? '') + ' ' + (snippet ?? '')).toLowerCase();
  const raw =
    /assignment|homework|submit/.test(t) ? 'assignment' :
    /exam|quiz|test/.test(t)             ? 'exam' :
    /event|seminar|workshop/.test(t)     ? 'event' :
    /deadline|due|reminder/.test(t)      ? 'deadline_reminder' :
    /club|activity/.test(t)              ? 'club_activity' :
    /scholarship/.test(t)                ? 'scholarship' :
    /announce|announcement/.test(t)      ? 'course_announcement' :
    /admin|registration|form/.test(t)    ? 'administrative' :
    'other';
  return safeMultiSelect(field, [raw]);
}

function inferConfidence(email, fields) {
  if (!email.Subject && !email.snippet) return 'low';
  const subject = (email.Subject ?? '').toLowerCase();
  const hasUrgency = /urgent|asap|critical|deadline|due|exam|submit/.test(subject);
  const hasContent = Object.keys(fields).length >= 3;
  if (hasUrgency && hasContent) return 'high';
  if (hasContent) return 'medium';
  return 'low';
}

function guessRole(name) {
  const n = name.toLowerCase();
  if (/priority/.test(n))                           return 'priority';
  if (/status/.test(n))                             return 'status';
  if (/due|deadline/.test(n))                       return 'due_date';
  if (/start/.test(n))                              return 'start_date';
  if (/tag|label|categor|topic/.test(n))            return 'tags';
  if (/short.*desc|summary/.test(n))                return 'description';
  if (/remark|note|detail/.test(n))                 return 'remarks';
  if (/request|from|sender|contact|assign/.test(n)) return 'requestor';
  if (/time|hour|duration|effort/.test(n))          return 'duration';
  return null;
}

const fields = {};
const skipped = [];
const task_name = stripEmoji(email.Subject);
const internalMs = parseInt(email.internalDate ?? Date.now());

schema.fields.forEach(f => {
  if (READ_ONLY.includes(f.type)) { skipped.push(f.name); return; }
  if (f.type === 'title') return;

  const role = guessRole(f.name);
  let value = null;

  if (f.type === 'status') {
    value = safeSelect(f, f.options?.[0] ?? null);
  } else if (f.type === 'select' && role === 'priority') {
    value = inferPriority(f, email.Subject, email.snippet);
  } else if (f.type === 'select') {
    value = safeSelect(f, f.options?.[0] ?? null);
  } else if (f.type === 'multi_select' && role === 'tags') {
    value = inferCategory(f, email.Subject, email.snippet);
  } else if (f.type === 'multi_select') {
    value = [];
  } else if (f.type === 'date' && role === 'due_date') {
    value = new Date(internalMs + 7 * 864e5).toISOString().split('T')[0];
  } else if (f.type === 'date' && role === 'start_date') {
    value = new Date(internalMs).toISOString().split('T')[0];
  } else if (f.type === 'date') {
    value = new Date(internalMs).toISOString().split('T')[0];
  } else if (f.type === 'rich_text' && role === 'description') {
    value = (email.snippet ?? '').slice(0, 200).trim();
  } else if (f.type === 'rich_text' && role === 'remarks') {
    value = 'Source: ' + ((email.From ?? '').match(/@([^>]+)/)?.[1] ?? 'unknown');
  } else if (f.type === 'rich_text') {
    value = null;
  } else if (f.type === 'checkbox') {
    value = false;
  } else if (f.type === 'number') {
    value = null;
  }

  if (value !== null && value !== '' && !(Array.isArray(value) && value.length === 0)) {
    fields[f.name] = value;
  }
});

const confidence = inferConfidence(email, fields);
const senderDomain = (email.From ?? '').match(/@([^>]+)/)?.[1] ?? 'unknown';

return [{ json: {
  task_name,
  fields,
  confidence,
  skipped,
  notes: 'Auto-created from email. Sender: ' + senderDomain + '. Validated against schema "' + schema.database_name + '".'
}}];

const properties = $input.first().json.properties;

const typeHandlers = {
  title:            (name, _p) => ({ name, type: "title",        required: true }),
  rich_text:        (name, _p) => ({ name, type: "rich_text" }),  // keep original, not "text"
  number:           (name, _p) => ({ name, type: "number" }),
  select:           (name,  p) => ({ name, type: "select",       options: p.select?.options?.map(o => o.name) ?? [] }),
  multi_select:     (name,  p) => ({ name, type: "multi_select", options: p.multi_select?.options?.map(o => o.name) ?? [] }),
  date:             (name, _p) => ({ name, type: "date" }),
  checkbox:         (name, _p) => ({ name, type: "checkbox" }),
  url:              (name, _p) => ({ name, type: "url" }),
  email:            (name, _p) => ({ name, type: "email" }),
  phone_number:     (name, _p) => ({ name, type: "phone_number" }),
  people:           (name, _p) => ({ name, type: "people" }),
  relation:         (name, _p) => ({ name, type: "relation" }),
  rollup:           (name, _p) => ({ name, type: "rollup",        note: "Auto-calculated from relation" }),
  formula:          (name, _p) => ({ name, type: "formula",       note: "Auto-calculated, read-only" }),
  status:           (name,  p) => ({ name, type: "status",       options: p.status?.options?.map(o => o.name) ?? [] }),
  created_time:     (name, _p) => ({ name, type: "created_time",       note: "Auto-set, read-only" }),
  last_edited_time: (name, _p) => ({ name, type: "last_edited_time",   note: "Auto-set, read-only" }),
};

const fields = Object.entries(properties).map(([name, prop]) => {
  const handler = typeHandlers[prop.type];
  return handler ? handler(name, prop) : { name, type: prop.type };
});

fields.sort((a, b) => {
  if (a.type === "title") return -1;
  if (b.type === "title") return 1;
  return a.name.localeCompare(b.name);
});

// Expose database_name from actual Notion data
const dbTitle = $input.first().json.title?.[0]?.plain_text ?? "Unknown";
return [{ json: { database_name: dbTitle, fields } }];

const input = $input.first().json;
const schema = $node["Transform Schema"].json;
const DATABASE_ID = $('Get a database').first().json.id;

// Build type map from live schema — no hardcoding
const schemaMap = Object.fromEntries(schema.fields.map(f => [f.name, f.type]));

const properties = {};

// Title field — find it dynamically from schema
const titleField = schema.fields.find(f => f.type === 'title');
if (titleField) {
  properties[titleField.name] = {
    title: [{ text: { content: input.task_name ?? '' } }]
  };
}

for (const [key, value] of Object.entries(input.valid_fields ?? {})) {
  const type = schemaMap[key];
  if (!type || value === null || value === undefined) continue;
  if (typeof value === 'object' && !Array.isArray(value)) continue; // skip malformed

  if (type === "select")       properties[key] = { select: { name: value } };
  if (type === "status")       properties[key] = { status: { name: value } };
  if (type === "multi_select") properties[key] = { multi_select: (Array.isArray(value) ? value : [value]).map(v => ({ name: v })) };
  if (type === "date")         properties[key] = { date: { start: value } };
  if (type === "rich_text")    properties[key] = { rich_text: [{ text: { content: String(value) } }] };
  if (type === "checkbox")     properties[key] = { checkbox: Boolean(value) };
  if (type === "number")       properties[key] = { number: Number(value) };
  if (type === "url")          properties[key] = { url: String(value) };
  if (type === "email")        properties[key] = { email: String(value) };
  if (type === "phone_number") properties[key] = { phone_number: String(value) };
}

return [{ json: { parent: { database_id: DATABASE_ID }, properties } }];

